mapper.select:
SELECT id, product_id, operation_type, quantity, before_stock, after_stock, reason, operator_id, operated_at
FROM inventory_records
WHERE product_id = #{productId}
ORDER BY operated_at DESC
LIMIT #{offset}, #{limit}

SELECT ir.id, ir.product_id, ir.operation_type, ir.quantity, ir.before_stock, ir.after_stock, ir.reason, ir.operator_id, ir.operated_at FROM inventory_records ir
LEFT JOIN products p ON ir.product_id = p.id
AND ir.product_id = #{productId}
AND p.name LIKE CONCAT('%', #{productName}, '%')
AND ir.operation_type = #{operationType}
AND ir.operator_id = #{operatorId}
ORDER BY ir.operated_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM inventory_records ir

    LEFT JOIN products p ON ir.product_id = p.id



        AND ir.product_id = #{productId}


        AND p.name LIKE CONCAT('%', #{productName}, '%')


        AND ir.operation_type = #{operationType}


        AND ir.operator_id = #{operatorId}

SELECT id, product_id, operation_type, quantity, before_stock, after_stock, reason, operator_id, operated_at
FROM inventory_records
WHERE product_id = #{productId}
ORDER BY operated_at DESC
LIMIT #{limit}

SELECT id, product_id, operation_type, quantity, before_stock, after_stock, reason, operator_id, operated_at
FROM inventory_records
WHERE operator_id = #{operatorId}
ORDER BY operated_at DESC
LIMIT #{offset}, #{limit}
